2	
3	import java.time.Clock;
4	import java.util.Optional;
5	import java.util.function.Supplier;
6	
7	import org.springframework.stereotype.Service;
8	
9	import com.example.starter.maintenance.api.ApiException;
10	import com.example.starter.maintenance.store.EquipmentRepository;
11	import com.example.starter.maintenance.store.EquipmentRepository.IdempotencyRow;
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	
14	/**
15	 * 幂等去重：requestId 全局唯一；同键同参重放原成功结果，同键异参返回 409。
16	 * 去重记录与业务变更在同一事务提交；业务失败抛异常回滚，不占键。
17	 * 调用方须先取得设备行锁再调用本服务，保证同设备并发重放的一致性。
18	 */
19	@Service
20	public class IdempotencyService {
21	
22	    private final EquipmentRepository repository;
23	    private final ObjectMapper objectMapper;
24	    private final Clock clock;
25	
26	    public IdempotencyService(EquipmentRepository repository, ObjectMapper objectMapper, Clock clock) {
27	        this.repository = repository;
28	        this.objectMapper = objectMapper;
29	        this.clock = clock;
30	    }
31	
32	    /**
33	     * 在调用方事务内执行幂等写操作。
34	     *
35	     * @param requestId   全局唯一请求标识
36	     * @param operation   操作类型
37	     * @param fingerprint 业务参数指纹（不含 requestId）
38	     * @param type        响应类型（用于重放反序列化）
39	     * @param action      业务动作，仅首次执行；抛异常则整体回滚、不占键
40	     */
41	    public <T> T execute(String requestId, String operation, String fingerprint,
42	                         Class<T> type, Supplier<T> action) {
43	        Optional<IdempotencyRow> existing = repository.findIdempotency(requestId);
44	        if (existing.isPresent()) {
45	            return replay(existing.get(), operation, fingerprint, type);
46	        }
47	        T result = action.get();
48	        repository.insertIdempotency(requestId, operation, fingerprint, writeJson(result), clock.instant());
49	        return result;
50	    }
51	
52	    /** 事务外重放：用于并发唯一键冲突后的补偿查询。 */
53	    public <T> T replayExisting(String requestId, String operation, String fingerprint, Class<T> type) {
54	        Optional<IdempotencyRow> existing = repository.findIdempotency(requestId);
55	        if (existing.isEmpty()) {
56	            return null;
57	        }
58	        return replay(existing.get(), operation, fingerprint, type);
59	    }
