    @Test
    void reviseReading_recomputesDeduction() throws Exception {
        register("eq-rr", 1000);
        addReading("eq-rr", "rr-r1", 1, "r1", "2026-01-01T10:00:00Z", 100, 201);
        addReading("eq-rr", "rr-r2", 2, "r2", "2026-01-01T11:00:00Z", 200, 201);
